with open('Ppcg23.html', 'r', encoding='latin1') as f:
    content = f.read()

import re
# Find TELEC section
start = content.find('id=\"TELEC\"')
# Find next variable after TELEC
next_var_match = re.search(r'id=\"TEL', content[start+10:])
if next_var_match:
    end = start + 10 + next_var_match.start()
else:
    end = len(content)
section = content[start:end]
print(section)
