result = subprocess.run(['pdftotext', '-layout', '2023NSCG_RecodeDocumentation_4Feb25.pdf', '-'], capture_output=True, text=True)
# Search for TELEC and employer size in recode doc
lines = result.stdout.split('\n')
for i, line in enumerate(lines):
    if 'TELEC' in line or 'telework' in line.lower() or 'employer size' in line.lower() or 'EMSIZE' in line:
        start = max(0,i-2)
        end = min(len(lines),i+5)
        for j in range(start, end):
            print(f'{j}: {lines[j]}')
        print('---')
